/* Ironlog — the UI kit. The small pieces every screen is built from: toast,
   modal sheets and the confirm dialog, the progress bar, line charts, the
   accessibility pass, and debug mode's "how?" button. Moved out of ui.js so a
   feature can open a sheet without importing the app shell (ui.js) and, through
   it, every other feature. Depends only on core.js and state.js. */
/* imports — generated by r&d/tools/module-map.cjs --sync, not by hand */
import { $, APP_VERSION, U, clamp, esc, nice, parseISO, today } from './core.js';
import { S } from './state.js';
/* end imports */

/* Tapping a set field selects what's in it, so typing replaces the number
   rather than appending to it — mid-session you are overwriting the last
   set's value, not editing one digit of it. On focus only: once the field is
   open a second tap places a caret as usual. select() rather than
   setSelectionRange because Chrome throws on selectionStart for
   input[type=number]; deferred a tick so the browser's own caret placement
   (which lands after focus on touch) doesn't collapse the selection. */
export function selectOnFocus(inp) {
  inp.onfocus = () => setTimeout(() => {
    try { inp.select(); } catch (e) { /* not selectable — leave the caret */ }
  }, 0);
}

/* ---------------- accessibility (roadmap C4) ----------------
   One pass over whatever was just drawn, run after every render and every
   modal, and again when a modal redraws itself: names for controls whose
   meaning comes from their row, labels tied to their fields, table headers
   that say something. Doing it here rather than in each template keeps the
   hundred-odd templates readable and means a new one is covered by default. */
let _lblSeq = 0;
const SET_FIELD = { w: () => `weight (${U()})`, r: () => 'reps', rpe: () => 'RIR', sec: () => 'time', m: () => 'metres', n: () => 'implements' };
export function a11yPass(root) {
  if (!root || !root.querySelectorAll) return;
  // a visible label beside a control, but not tied to it
  root.querySelectorAll('.field').forEach(f => {
    const lab = f.querySelector(':scope > label');
    const ctl = f.querySelector('input:not([type=hidden]):not([type=checkbox]):not([type=radio]), select, textarea');
    if (!lab || !ctl || lab.contains(ctl) || ctl.hasAttribute('aria-label') || ctl.hasAttribute('aria-labelledby')) return;
    if (ctl.id && lab.htmlFor === ctl.id) return;
    if (!lab.id) lab.id = 'lb' + (++_lblSeq);
    ctl.setAttribute('aria-labelledby', lab.id);
  });
  // set rows: every box and button says which set it belongs to
  root.querySelectorAll('tr[data-row], .settable tbody tr').forEach(tr => {
    const no = tr.querySelector('.setno');
    const n = no ? no.textContent.trim() : '';
    const set = n === 'W' ? 'Warm-up set' : n === '↳' ? 'Drop set' : `Set ${n.replace(/^[TBA]/, '')}`;
    tr.querySelectorAll('input[data-f], input[data-ef]').forEach(i => {
      if (i.hasAttribute('aria-label') && !i.dataset.a11y) return;
      const f = SET_FIELD[i.dataset.f || i.dataset.ef];
      if (f) { i.setAttribute('aria-label', `${set} ${f()}`); i.dataset.a11y = '1'; }
    });
    const chk = tr.querySelector('.chk');
    if (chk) { chk.setAttribute('aria-label', `${set} done`); chk.setAttribute('aria-pressed', chk.classList.contains('on') ? 'true' : 'false'); }
    const del = tr.querySelector('.delset');
    if (del) del.setAttribute('aria-label', `Delete ${set.toLowerCase()}`);
    const pl = tr.querySelector('[data-plates]');
    if (pl) pl.setAttribute('aria-label', `Plates for ${set.toLowerCase()}`);
  });
  root.querySelectorAll('.settable th').forEach(th => {
    if (th.textContent.trim()) return;
    const w = th.classList.contains('c-del') ? 'Delete' : th.classList.contains('c-pl') ? 'Tools' : th.classList.contains('c-chk') ? 'Done' : 'Actions';
    th.innerHTML = `<span class="sr">${w}</span>`;
  });
  root.querySelectorAll('[data-ex-menu]').forEach(b => b.setAttribute('aria-label', 'Exercise options'));
  root.querySelectorAll('.setno[data-warm], .setno[data-ewarm]').forEach(b => b.setAttribute('aria-haspopup', 'dialog'));
  // the current tab, said rather than only coloured
  root.querySelectorAll('.seg').forEach(s => s.querySelectorAll('button').forEach(b => b.setAttribute('aria-pressed', b.classList.contains('on') ? 'true' : 'false')));
}
// redraws inside a modal (tabs, lists) replace their HTML — cover those too
new MutationObserver(ms => {
  const roots = new Set(ms.map(m => m.target.closest ? (m.target.closest('.modal') || m.target.closest('#view')) : null).filter(Boolean));
  roots.forEach(a11yPass);
}).observe(document.body, { childList: true, subtree: true });

export function toast(msg, cls = '') {
  const el = document.createElement('div');
  el.className = 'toast ' + cls;
  el.textContent = msg;   // plain text only — exercise names come from the user, CSV imports and JSON files
  $('#toastRoot').appendChild(el);
  setTimeout(() => { el.style.transition = 'opacity .3s'; el.style.opacity = '0'; setTimeout(() => el.remove(), 320); }, 2400);
}

export let modalStack = [];
export function modal({ title, body, foot, onOpen, wide, sticky, onClose }) {
  const bg = document.createElement('div');
  bg.className = 'modal-bg';
  const hid = 'mh' + (++modalSeq);
  bg.innerHTML = `
    <div class="modal" role="dialog" aria-modal="true" aria-labelledby="${hid}">
      <div class="modal-head"><h2 id="${hid}" tabindex="-1">${esc(title)}</h2><button class="icon-btn" data-close aria-label="Close">✕</button></div>
      <div class="modal-body" tabindex="0">${body}</div>
      ${foot ? `<div class="modal-foot">${foot}</div>` : ''}
    </div>`;
  bg._ret = document.activeElement;   // focus goes back here when it closes
  /* sticky: a stray tap on the backdrop must not end a running timer. */
  bg.addEventListener('click', e => {
    if ((e.target === bg && !sticky) || e.target.hasAttribute('data-close')) {
      if (bg._guard && !bg._guard()) return;   // a sheet with unsaved work asks first
      closeModal(); if (onClose) onClose();
    }
  });
  $('#modalRoot').appendChild(bg);
  modalStack.push(bg);
  if (onOpen) onOpen(bg);
  a11yPass(bg);
  // a screen reader lands on the title, unless onOpen already put focus somewhere inside
  if (!bg.contains(document.activeElement)) { try { $('h2', bg).focus({ preventScroll: true }); } catch (e) { /* old browser */ } }
  return bg;
}
let modalSeq = 0;
export function closeModal() {
  const m = modalStack.pop();
  if (!m) return;
  m.remove();
  const r = m._ret;
  if (r && document.body.contains(r) && typeof r.focus === 'function') { try { r.focus({ preventScroll: true }); } catch (e) { /* gone */ } }
}
export function closeAllModals() { modalStack.forEach(m => m.remove()); modalStack = []; }

export function confirmDlg(msg, onYes, yesLabel = 'Delete', onNo) {
  modal({
    title: 'Are you sure?',
    body: `<p style="margin:0;color:var(--dim)">${esc(msg)}</p>`,
    foot: `<button class="btn ghost" id="cfmNo" data-close>Cancel</button><button class="btn danger" id="cfmYes">${esc(yesLabel)}</button>`,
    onOpen: bg => {
      $('#cfmYes', bg).onclick = () => { closeModal(); onYes(); };
      if (onNo) $('#cfmNo', bg).onclick = () => { closeModal(); onNo(); };
    },
  });
}

export function bar(pct, cls = '') {
  const p = clamp(pct, 0, 100);
  return `<div class="bar ${p >= 100 ? 'done' : cls}"><i style="width:${p}%"></i></div>`;
}

/* line chart: data = [{date, v}] */
/* One line per variant, overlaid on a shared date axis. Section 4.5: never
   merged, never averaged — aggregating across variants is a lie, because a
   machine press and a competition bench are not the same lift. Series may
   cover different dates, so the x axis is the union of all of them. */
export const SERIES_COLORS = ['var(--accent)', 'var(--blue)', 'var(--green)', 'var(--purple)', 'var(--gold)'];
export function chartMulti(series, { h = 170, fmt = v => nice(v) } = {}) {
  const live = series.filter(s => s.points.length);
  if (!live.length) return `<div class="empty">No data yet</div>`;
  const dates = [...new Set(live.flatMap(s => s.points.map(p => p.date)))].sort();
  const vals = live.flatMap(s => s.points.map(p => p.v));
  let min = Math.min(...vals), max = Math.max(...vals);
  if (min === max) { min = min * 0.95 || 0; max = max * 1.05 || 1; }
  const span = max - min || 1;
  min -= span * 0.08; max += span * 0.08;
  const W = 320, H = h, padL = 34, padR = 8, padT = 12, padB = 20;
  const x = d => padL + (dates.length === 1 ? (W - padL - padR) / 2
    : dates.indexOf(d) * (W - padL - padR) / (dates.length - 1));
  const y = v => padT + (1 - (v - min) / (max - min)) * (H - padT - padB);

  let grid = '';
  for (let i = 0; i <= 4; i++) {
    const v = min + (max - min) * (i / 4), yy = y(v);
    grid += `<line class="grid" x1="${padL}" x2="${W - padR}" y1="${yy.toFixed(1)}" y2="${yy.toFixed(1)}" opacity=".5"/>
             <text class="axis" x="${padL - 5}" y="${(yy + 3).toFixed(1)}" text-anchor="end">${fmt(v)}</text>`;
  }
  const lines = live.map((s, si) => {
    const c = s.color || SERIES_COLORS[si % SERIES_COLORS.length];
    const pts = s.points.map(p => [x(p.date), y(p.v)]);
    const d = pts.map((p, i) => `${i ? 'L' : 'M'}${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(' ');
    // inline style, not the stroke attribute: .chart .ln in the stylesheet outranks an attribute
    return `<path class="ln" d="${d}" style="stroke:${c}" fill="none"/>` +
      pts.map(p => `<circle cx="${p[0].toFixed(1)}" cy="${p[1].toFixed(1)}" r="2.6" fill="${c}"/>`).join('');
  }).join('');
  const labIdx = dates.length <= 2 ? dates.map((_, i) => i) : [0, Math.floor((dates.length - 1) / 2), dates.length - 1];
  const xlabs = labIdx.map(i => {
    const anchor = i === 0 ? 'start' : i === dates.length - 1 ? 'end' : 'middle';
    return `<text class="axis" x="${x(dates[i]).toFixed(1)}" y="${H - 5}" text-anchor="${anchor}">${parseISO(dates[i]).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}</text>`;
  }).join('');
  const legend = live.length > 1 ? `<div class="legend">${live.map((s, si) =>
    `<span><i style="background:${s.color || SERIES_COLORS[si % SERIES_COLORS.length]}"></i>${esc(s.label)}</span>`).join('')}</div>` : '';
  return `<div class="chartbox"><svg class="chart" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" style="height:${H}px">
    ${grid}${lines}${xlabs}</svg>${legend}</div>`;   // legend inside the box: the 98 skin restates colours per surface, so outside it the swatches drift from the lines
}

export function chart(data, { color = 'var(--accent)', h = 150, fmt = v => nice(v) } = {}) {
  if (data.length === 0) return `<div class="empty">No data yet</div>`;
  const W = 320, H = h, padL = 34, padR = 8, padT = 12, padB = 20;
  const vals = data.map(d => d.v);
  let min = Math.min(...vals), max = Math.max(...vals);
  if (min === max) { min = min * 0.95 || 0; max = max * 1.05 || 1; }
  const span = max - min || 1;
  min -= span * 0.08; max += span * 0.08;
  const x = i => padL + (data.length === 1 ? (W - padL - padR) / 2 : i * (W - padL - padR) / (data.length - 1));
  const y = v => padT + (1 - (v - min) / (max - min)) * (H - padT - padB);

  const pts = data.map((d, i) => [x(i), y(d.v)]);
  const line = pts.map((p, i) => `${i ? 'L' : 'M'}${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(' ');
  const area = `${line} L${pts[pts.length - 1][0].toFixed(1)},${H - padB} L${pts[0][0].toFixed(1)},${H - padB} Z`;
  const bestIdx = vals.indexOf(Math.max(...vals));

  const ticks = 4;
  let grid = '';
  for (let i = 0; i <= ticks; i++) {
    const v = min + (max - min) * (i / ticks);
    const yy = y(v);
    grid += `<line class="grid" x1="${padL}" x2="${W - padR}" y1="${yy.toFixed(1)}" y2="${yy.toFixed(1)}" opacity=".5"/>
             <text class="axis" x="${padL - 5}" y="${(yy + 3).toFixed(1)}" text-anchor="end">${fmt(v)}</text>`;
  }
  // x labels: first, middle, last
  const labIdx = data.length <= 2 ? data.map((_, i) => i) : [0, Math.floor((data.length - 1) / 2), data.length - 1];
  const xlabs = labIdx.map(i => {
    const d = parseISO(data[i].date);
    const anchor = i === 0 ? 'start' : i === data.length - 1 ? 'end' : 'middle';
    return `<text class="axis" x="${x(i).toFixed(1)}" y="${H - 5}" text-anchor="${anchor}">${d.toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}</text>`;
  }).join('');

  return `<div class="chartbox"><svg class="chart" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" style="height:${H}px">
    <defs><linearGradient id="gfade" x1="0" x2="0" y1="0" y2="1">
      <stop offset="0%" stop-color="${color}" stop-opacity=".28"/>
      <stop offset="100%" stop-color="${color}" stop-opacity="0"/>
    </linearGradient></defs>
    ${grid}
    <path class="area" d="${area}"/>
    <path class="ln" d="${line}" style="stroke:${color}"/>
    ${pts.map((p, i) => `<circle class="pt${i === bestIdx ? ' best' : ''}" cx="${p[0].toFixed(1)}" cy="${p[1].toFixed(1)}" r="${i === bestIdx ? 4 : 3}" fill="${i === bestIdx ? 'var(--gold)' : color}"/>`).join('')}
    ${xlabs}
  </svg></div>`;
}

/* ---------------- debug mode: the "how?" button (E11) ----------------
   The explainers themselves are in ui.js, which fills WHY at load; only the
   registry and the button live here. */
export const WHY = {};
export const debugOn = () => !!S.settings.debug;
export function why(kind, ...args) {
  if (!debugOn()) return '';
  const X = WHY[kind];
  return `<button type="button" class="why" data-why="${kind}" data-wa="${esc(JSON.stringify(args))}" aria-label="Show the working for ${esc(X ? X.label : kind)}">how?</button>`;
}

/* ============================================================
   ROUTER — which page is showing, and the state the pages keep between draws.
   render() and applySkin() are hooks: ui.js, which draws the pages, fills
   them in when it loads. So a feature can redraw or change page without
   importing the shell and, through it, every other feature.
   ============================================================ */
export const shell = { render() {}, applySkin() {} };
export function render() { shell.render(); }
export function applySkin(skin) { shell.applySkin(skin); }
export let page = 'home';
export let calCursor = new Date();          // month shown
export let calSelected = today();
export let analyticsSort = 'sessions';
export let analyticsTab = 'exercises';   // exercises | rankings | muscles — one screen each, not one long scroll
export let analyticsQuery = '';
export let whatsNewArmed = false, whatsNewBusy = false;
/* The cardio loop's latest call, kept only while debug mode is on. */
export let cardioWhyLast = null;
/* Setters: these are assigned from other modules, and an import is read-only. */
export function setPage(x) { return page = x; }
export function setCalCursor(x) { return calCursor = x; }
export function setCalSelected(x) { return calSelected = x; }
export function setAnalyticsSort(x) { return analyticsSort = x; }
export function setAnalyticsTab(x) { return analyticsTab = x; }
export function setAnalyticsQuery(x) { return analyticsQuery = x; }
export function setWhatsNewArmed(x) { return whatsNewArmed = x; }
export function setWhatsNewBusy(x) { return whatsNewBusy = x; }
export function setCardioWhyLast(x) { return cardioWhyLast = x; }

/* Events live under Calendar since D12 (r&d/specs/layout-spec.md): the page id
   stays 'meets' so every old route still lands, but Calendar's tab lights. */
export const NAV_TAB = { meets: 'calendar' };
export function go(p) {
  if (p === 'food') p = 'home';   // the Food tab is gone (0.25.0)
  page = p;
  render();
  window.scrollTo(0, 0);
}

/* Calendar | Events — one tab, two views (D12). */
export function calSwitch() {
  return `<div class="seg" style="margin-bottom:13px">
    <button data-go="calendar" class="${page === 'calendar' ? 'on' : ''}">Calendar</button>
    <button data-go="meets" class="${page === 'meets' ? 'on' : ''}">Events</button>
  </div>`;
}

/* ---------------- debug mode: the walk-through sheet (E11) ---------------- */
export function trace(title) {
  const t = { title, rows: [], checks: [] };
  const val = v => v == null || v === '' ? '—' : String(v);
  t.head = text => { t.rows.push({ h: text }); return t; };
  t.step = (label, value, note) => { t.rows.push({ label, value: val(value), note: note || '' }); return t; };
  t.result = (label, value, note) => { t.rows.push({ label, value: val(value), note: note || '', res: true }); return t; };
  t.note = text => { t.rows.push({ p: text }); return t; };
  /* The walk-through's answer against the app's: a mismatch is a bug in one of them. */
  t.check = function (what, mine, app, fmt) {
    fmt = fmt || String;
    const same = typeof mine === 'number' && typeof app === 'number'
      ? Math.abs(mine - app) <= 1e-6 * Math.max(1, Math.abs(app)) : String(mine) === String(app);
    t.checks.push({ what, same, mine: fmt(mine), app: fmt(app) });
    return t;
  };
  return t;
}
export function traceText(t) {
  const out = [`How: ${t.title}`, `Ironlog ${APP_VERSION} · ${new Date().toLocaleString()}`, ''];
  t.rows.forEach(r => {
    if (r.h) out.push('', `== ${r.h} ==`);
    else if (r.p) out.push(r.p);
    else out.push(`${r.res ? '→ ' : ''}${r.label}: ${r.value}${r.note ? `  (${r.note})` : ''}`);
  });
  if (t.checks.length) out.push('');
  t.checks.forEach(c => out.push(c.same ? `✓ ${c.what} matches what the app shows (${c.app})` : `✗ ${c.what}: walk-through ${c.mine}, app shows ${c.app}`));
  return out.join('\n');
}
function traceHtml(t) {
  const rows = t.rows.map(r => r.h ? `<tr class="wh"><th colspan="2" scope="colgroup">${esc(r.h)}</th></tr>`
    : r.p ? `<tr><td colspan="2" class="sub">${esc(r.p)}</td></tr>`
    : `<tr${r.res ? ' class="res"' : ''}><td>${esc(r.label)}${r.note ? `<div class="sub">${esc(r.note)}</div>` : ''}</td><td class="r mono">${esc(r.value)}</td></tr>`).join('');
  return `<table class="whytab"><thead><tr><th scope="col">Step</th><th scope="col" class="r">Value</th></tr></thead><tbody>${rows}</tbody></table>
    ${t.checks.map(c => `<div class="whyok ${c.same ? 'ok' : 'bad'}" role="status">${c.same
      ? `✓ ${esc(c.what)} matches what the app shows (${esc(c.app)})`
      : `✗ ${esc(c.what)}: this walk-through gives ${esc(c.mine)} but the app shows ${esc(c.app)}. Copy the trace and report it.`}</div>`).join('')}`;
}
export async function copyText(text, msg) {
  try { await navigator.clipboard.writeText(text); toast(msg, 'green'); }
  catch (e) {
    const ta = document.createElement('textarea');
    ta.value = text; ta.setAttribute('readonly', ''); ta.style.cssText = 'position:fixed;opacity:0';
    document.body.appendChild(ta); ta.select();
    let ok = false; try { ok = document.execCommand('copy'); } catch (e2) { /* no copy at all */ }
    ta.remove();
    toast(ok ? msg : 'Could not copy');
  }
}
export function openWhy(kind, args) {
  const X = WHY[kind];
  if (!X) return;
  let t;
  try { t = X.fn(...(args || [])); }
  catch (e) { console.warn('why', kind, e); t = trace(X.label).note(`Couldn't build this trace: ${e.message}`); }
  if (!t) return toast('Nothing to show the working for any more');
  modal({
    title: `How: ${t.title}`,
    body: traceHtml(t),
    foot: `<button class="btn ghost" id="whyCopy">Copy trace</button><button class="btn primary" data-close>Done</button>`,
    onOpen: bg => { $('#whyCopy', bg).onclick = () => copyText(traceText(t), 'Trace copied'); },
  });
}
/* Captured before any row handler, so "how?" inside a tappable row opens the
   trace and not the row. */
document.addEventListener('click', ev => {
  const b = ev.target.closest && ev.target.closest('[data-why]');
  if (!b) return;
  ev.stopPropagation(); ev.preventDefault();
  let a = [];
  try { a = JSON.parse(b.dataset.wa || '[]'); } catch (e) { /* bad args: open with none */ }
  openWhy(b.dataset.why, a);
}, true);

/* ---------------- the medical disclaimer (Welcome, Help and the coach) ---------------- */
/* ============================================================
   WELCOME AND HELP — roadmap C1
   Three short steps on a fresh install: what Ironlog is (and isn't), units
   and the lifter, what they're training for. Only ever on a device with no
   sessions and no check-ins, and only until it's been finished or skipped —
   a restore or an import on step one ends it too.
   ============================================================ */
export const DISCLAIMER = 'Ironlog gives general training information, not medical or physiotherapy advice. If you have an injury or a health condition, check with a professional first. You are responsible for what you lift — use safeties, spotters and judgement.';

/* ---------------- help text (the FAQ: Help and the coach both read it) ---------------- */
/* Help & FAQ: short answers to the questions the app raises. */
export const FAQ = [
  ['Where is my data?', 'On this phone, in the browser\'s storage for this app. There is no Ironlog account or server. Settings shows whether the phone has agreed not to clear it when space runs low.'],
  ['How do I back up or move to a new phone?', 'Settings → Google Drive → Connect keeps a copy in your own Drive and merges between phones — on a new phone, connect and your log comes down. Or Settings → Export JSON saves a file you can import anywhere.'],
  ['What is RIR?', 'Reps in reserve: how many more reps you could have done. 0 is to failure, 2 means two left in the tank. Ironlog stores it as RPE (10 − RIR) for its maths.'],
  ['What is e1RM?', 'Estimated one-rep max, worked out from a set\'s weight, reps and RIR. It lets a 100 kg × 5 be compared with a 110 kg × 2.'],
  ['What counts as a PR?', 'A set that beats your history for that exact exercise variant — heavier at the same reps, more reps at the same weight, or a better e1RM. Warm-ups and drop sets never count. Holds, carries and time caps have their own records.'],
  ['What are set roles?', 'Tap a set\'s number to mark it warm-up, working, top set, back-off, AMRAP or drop set. Warm-ups stay out of volume and PRs; drops count for volume but not PRs.'],
  ['How do I log faster?', 'Ticking an empty set logs what you did last time. Tap Prev to fill a row, use the − / + bar under the table, or Copy down.'],
  ['Can I bring in my history from another app?', 'Settings → Data → Import CSV reads exports from Strong, Hevy, FitNotes and Liftoff, or any CSV with date, exercise, weight and reps. You see exactly what will be added before anything is saved, and can remove an import later.'],
  ['What does the AI do, and what does it cost?', 'It\'s optional: it helps parse free-text notes when you add your own Anthropic API key in Settings. The key stays on this phone and calls go straight to Anthropic, billed to your key. Nothing needs it.'],
  ['How do updates work?', 'The app checks for a new version when it opens and asks before updating. What\'s new lists the changes.'],
  ['Is this medical advice?', DISCLAIMER],
];

/* ---------------- video clip recording (moved in from health.js, E17 phase 5) ---------------- */
/* ---- daily one-second clip (roadmap 03): this device only ----
   r&d/specs/progress-clip-spec.md. Every clip is re-recorded through one
   canvas at one size, so a timelapse is just the clips played back to back
   into that canvas while MediaRecorder captures it — real time, about a
   second per clip, on the phone, no upload, no library. */
export const CLIP = { w: 480, h: 640, fps: 30, bps: 1.5e6, ms: 1000, index: 'ironlog.clips' };
export function clipMime() {
  if (typeof MediaRecorder === 'undefined') return null;
  return ['video/mp4;codecs=avc1.42E01E', 'video/mp4', 'video/webm;codecs=vp9', 'video/webm;codecs=vp8', 'video/webm']
    .find(t => { try { return MediaRecorder.isTypeSupported(t); } catch (e) { return false; } }) || null;
}
/* Record `ms` of whatever the canvas shows. `draw` paints each frame. */
export function clipRecorder(canvas, opts = {}) {
  const mime = clipMime();
  const rec = new MediaRecorder(canvas.captureStream(CLIP.fps), { mimeType: mime, videoBitsPerSecond: opts.bps || CLIP.bps });
  const chunks = [];
  rec.ondataavailable = e => { if (e.data && e.data.size) chunks.push(e.data); };
  const done = new Promise(res => { rec.onstop = () => res(new Blob(chunks, { type: mime.split(';')[0] })); });
  return { start: () => rec.start(), stop: () => { if (rec.state !== 'inactive') rec.stop(); return done; } };
}
export function clipVideoEl(src) {
  const v = document.createElement('video');
  v.muted = true; v.playsInline = true; v.preload = 'auto';
  if (src) v.src = src;
  return v;
}

/* ---------------- saving a file (moved in from tools.js) ---------------- */
export function saveBlob(text, type, name) {
  const blob = new Blob([text], { type });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = name;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(a.href), 1000);
}
